"""Verify original administrative and sign records before trail construction.

The packet is a local source inventory. It cannot make a City designation,
dedication or sign legally sufficient; it binds asserted observations to bytes.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


RECORDS = {
    'map': ('map_sha256',),
    'corridor': ('corridor_source_sha256',),
    'official_plan_designation': ('administrative_records', 'official_plan_designation', 'source_sha256'),
    'city_trail_dedication': ('administrative_records', 'city_trail_dedication', 'source_sha256'),
    'sign_face': ('sign', 'face_readback_sha256'),
    'governed_access': ('sign', 'governed_access_sha256'),
    'vehicle_class': ('vehicle_class_source_sha256',),
    'operator': ('operator_source_sha256',),
    'exception_status': ('exception_status_source_sha256',),
}


def _get(site, key):
    path = RECORDS[key]
    value = site
    for part in path:
        value = value[part]
    return value


def verify_packet(site: dict, packet_path: Path) -> dict:
    """Return hashes only after each site claim joins an original source file."""
    root = packet_path.resolve().parent
    packet = json.loads(packet_path.read_text(encoding='utf-8'))
    if packet.get('cell_id') != 'C143687' or packet.get('layout') != 'nonmotorized_trail':
        raise ValueError('source packet cell mismatch')
    sources = packet.get('sources')
    if not isinstance(sources, dict) or set(sources) != set(RECORDS):
        raise ValueError('source packet record inventory incomplete')
    result = {}
    for key in RECORDS:
        entry = sources[key]
        relative = entry.get('path')
        if not isinstance(relative, str) or not relative or Path(relative).is_absolute():
            raise ValueError(f'{key} invalid source path')
        source = (root / relative).resolve()
        if root not in source.parents or not source.is_file():
            raise ValueError(f'{key} source outside packet or missing')
        digest = hashlib.sha256(source.read_bytes()).hexdigest()
        if digest != entry.get('sha256') or digest != _get(site, key):
            raise ValueError(f'{key} source hash mismatch')
        result[key] = digest
    assertions = packet.get('assertions', {})
    for key in ('official_plan_designation', 'city_trail_dedication'):
        actual = site['administrative_records'][key]['asserted']
        if type(assertions.get(key)) is not bool or assertions[key] is not actual:
            raise ValueError(f'{key} source assertion mismatch')
    sign = site['sign']
    if assertions.get('sign_face_text') != sign['face_text'] or (
        type(assertions.get('prohibits_motor_vehicles')) is not bool or
        assertions['prohibits_motor_vehicles'] is not sign['prohibits_motor_vehicles']
    ):
        raise ValueError('sign face source assertion mismatch')
    for key in ('emergency_use', 'maintenance_use'):
        if type(assertions.get(key)) is not bool or assertions[key] is not site[key]:
            raise ValueError(f'{key} source assertion mismatch')
    return {'cell_id': 'C143687', 'packet_sha256': hashlib.sha256(packet_path.read_bytes()).hexdigest(),
            'source_sha256': result, 'legal_judgment': None}

"""Independent original-frame and controlled-pair audits for the trail cases."""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path
from typing import Mapping


FIXED = ('cell_id', 'map_sha256', 'corridor_source_sha256', 'route_sha256',
         'vehicle_blueprint', 'operator_source_sha256', 'camera_plan_sha256',
         'duration_frames')
CONDITIONS = ('official_plan_designation', 'city_trail_dedication',
              'prohibits_motor_vehicles', 'emergency_use', 'maintenance_use')
CASE_CONDITIONS = {
    'all_prerequisites': (True, True, True, False, False),
    'not_designated': (False, True, True, False, False),
    'not_dedicated': (True, False, True, False, False),
    'no_prohibition_sign': (True, True, False, False, False),
    'emergency_vehicle': (True, True, True, True, False),
    'maintenance_vehicle': (True, True, True, False, True),
}
ASSIGNMENT_ID = 'testing__C143687__LVMC-11-27-010-A__motor_vehicle_driver'


def _case_suffix(case_id: str) -> str:
    prefix = ASSIGNMENT_ID + '__'
    if not isinstance(case_id, str) or not case_id.startswith(prefix):
        raise ValueError('foreign exact case')
    suffix = case_id[len(prefix):]
    if suffix not in CASE_CONDITIONS:
        raise ValueError('unknown exact case')
    return suffix


def audit_history(path: Path, expected_sha256: str, case_id: str,
                  expected_frames: int = 900) -> dict:
    suffix = _case_suffix(case_id)
    raw = path.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != expected_sha256:
        raise ValueError('original history hash mismatch')
    try:
        rows = [json.loads(line) for line in raw.decode('utf-8').splitlines() if line]
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('original history decode failed') from exc
    if len(rows) != expected_frames:
        raise ValueError('original history frame count mismatch')
    first = rows[0]
    if type(first.get('original_frame')) is not int:
        raise ValueError('original frame identity missing')
    baseline = {key: first.get(key) for key in FIXED + CONDITIONS +
                ('sign_face_sha256', 'governed_access_sha256',
                 'official_plan_source_sha256', 'dedication_source_sha256',
                 'exception_status_source_sha256')}
    if any(value is None or value == '' for value in baseline.values()):
        raise ValueError('fixed or administrative source missing')
    if baseline['cell_id'] != 'C143687' or baseline['duration_frames'] != expected_frames:
        raise ValueError('wrong cell or capture duration')
    observed = tuple(baseline[key] for key in CONDITIONS)
    if any(type(value) is not bool for value in observed) or observed != CASE_CONDITIONS[suffix]:
        raise ValueError('recorded conditions differ from exact case')
    entered = False
    sign_readback = False
    for index, row in enumerate(rows):
        if row.get('case_id') != case_id or row.get('original_frame') != first['original_frame'] + index:
            raise ValueError('case or original frame join mismatch')
        if any(row.get(key) != value for key, value in baseline.items()):
            raise ValueError('fixed source changed during capture')
        if not row.get('native_packet_sha256') or not row.get('vehicle_id') or not row.get('operator_id'):
            raise ValueError('Native actor source missing')
        if row.get('vehicle_id') != first.get('vehicle_id') or row.get('operator_id') != first.get('operator_id'):
            raise ValueError('actor identity changed')
        if type(row.get('vehicle_inside_corridor')) is not bool or type(row.get('sign_face_visible')) is not bool:
            raise ValueError('corridor or sign readback missing')
        entered |= row['vehicle_inside_corridor']
        sign_readback |= row['sign_face_visible']
    if not entered:
        raise ValueError('vehicle never entered trail corridor')
    if not sign_readback:
        raise ValueError('sign face was never read back')
    return {'case_id': case_id, 'original_history_sha256': digest,
            'frame_count': len(rows), 'entered_corridor': entered,
            'sign_face_readback': sign_readback, **baseline,
            'legal_judgment': None, 'physical_video_visibility_verified': False}


def audit_pair(left: Mapping, right: Mapping, deliberate_difference: str) -> dict:
    if deliberate_difference not in CONDITIONS:
        raise ValueError('undeclared comparison variable')
    for side in (left, right):
        if side.get('frame_count') != 900 or not side.get('original_history_sha256') or not side.get('entered_corridor'):
            raise ValueError('comparison original evidence incomplete')
        suffix = _case_suffix(side.get('case_id'))
        if tuple(side.get(key) for key in CONDITIONS) != CASE_CONDITIONS[suffix]:
            raise ValueError('comparison conditions differ from exact case')
    source_fields = ('governed_access_sha256', 'sign_face_sha256',
                     'official_plan_source_sha256', 'dedication_source_sha256',
                     'exception_status_source_sha256')
    variable_source = {
        'official_plan_designation': 'official_plan_source_sha256',
        'city_trail_dedication': 'dedication_source_sha256',
        'prohibits_motor_vehicles': 'sign_face_sha256',
        'emergency_use': 'exception_status_source_sha256',
        'maintenance_use': 'exception_status_source_sha256',
    }[deliberate_difference]
    for key in FIXED + tuple(x for x in CONDITIONS if x != deliberate_difference) + tuple(
            x for x in source_fields if x != variable_source):
        if key not in left or key not in right or left[key] != right[key]:
            raise ValueError(f'fixed condition changed: {key}')
    if deliberate_difference not in left or deliberate_difference not in right or left[deliberate_difference] == right[deliberate_difference]:
        raise ValueError('deliberate difference absent')
    if left[variable_source] == right[variable_source]:
        raise ValueError('difference has no distinct source')
    if left.get('case_id') == right.get('case_id'):
        raise ValueError('same exact case twice')
    return {'case_ids': [left['case_id'], right['case_id']],
            'difference': deliberate_difference,
            'source_hashes': [left['original_history_sha256'], right['original_history_sha256']],
            'legal_judgment': None}


def audit_packet_join(history_path, history_sha256, packet_path, packet_sha256,
                      corridor_box, case_id):
    """Independently bind every observed trail row to its original tick packet."""
    history_path, packet_path = Path(history_path), Path(packet_path)
    if hashlib.sha256(history_path.read_bytes()).hexdigest() != history_sha256:
        raise ValueError('original history hash mismatch')
    packet_bytes = packet_path.read_bytes()
    if hashlib.sha256(packet_bytes).hexdigest() != packet_sha256:
        raise ValueError('original packet stream hash mismatch')
    history = [json.loads(line) for line in history_path.read_text().splitlines() if line]
    packets = packet_bytes.splitlines(keepends=True)
    if len(history) != len(packets) or len(history) != 900:
        raise ValueError('original packet/history frame count mismatch')
    if (not isinstance(corridor_box, list) or len(corridor_box) != 4 or
            any(type(v) not in (int, float) or not math.isfinite(v) for v in corridor_box) or
            corridor_box[0] >= corridor_box[2] or corridor_box[1] >= corridor_box[3]):
        raise ValueError('reviewed corridor geometry missing')
    previous = None
    for index, (row, raw) in enumerate(zip(history, packets)):
        if hashlib.sha256(raw).hexdigest() != row.get('native_packet_sha256'):
            raise ValueError('history/packet hash join mismatch')
        packet = json.loads(raw)
        if (row.get('case_id') != case_id or row.get('original_frame') != packet.get('frame') or
                row.get('time_s') != packet.get('time_s') or
                row.get('vehicle_id') != packet.get('vehicle_id') or
                row.get('sign_face_visible') != packet.get('sign_face_visible')):
            raise ValueError('history/original packet identity or clock mismatch')
        point = packet.get('location_xy')
        if (not isinstance(point, list) or len(point) != 2 or
                any(type(v) not in (int, float) or not math.isfinite(v) for v in point)):
            raise ValueError('original packet location missing')
        inside = (corridor_box[0] <= point[0] <= corridor_box[2] and
                  corridor_box[1] <= point[1] <= corridor_box[3])
        if row.get('vehicle_inside_corridor') is not inside:
            raise ValueError('history/original packet corridor observation mismatch')
        frame, time_s = packet['frame'], packet['time_s']
        if previous is not None and (frame != previous[0] + 1 or
                                     not .049 <= time_s - previous[1] <= .051):
            raise ValueError('original packet 20 Hz clock discontinuity')
        previous = frame, time_s
    audited = audit_history(history_path, history_sha256, case_id)
    return {'case_id': case_id, 'original_history_sha256': history_sha256,
            'original_packets_sha256': packet_sha256, 'joined_frames': len(history),
            'entered_corridor': audited['entered_corridor'],
            'physical_video_visibility_verified': False, 'legal_judgment': None}

"""Independent saved-source integrity check for an exact trail attempt.

This audits original bytes and joins only. A caller still needs a full media
decode, actual-pixel review, physical-completion review and local acceptance.
"""
from __future__ import annotations

import hashlib
import importlib.util
import json
from pathlib import Path
import subprocess


_spec = importlib.util.spec_from_file_location('trail_saved_audit', Path(__file__).with_name('saved_audit.py'))
_saved = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(_saved)
CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')


def _sha(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def _confined(root: Path, relative: str) -> Path:
    if not isinstance(relative, str) or not relative or Path(relative).is_absolute():
        raise ValueError('invalid saved source path')
    path = (root / relative).resolve()
    if path == root or root not in path.parents or not path.is_file():
        raise ValueError('saved source missing or outside attempt')
    return path


def audit_saved(attempt: Path, acquisition_path: Path, case_id: str) -> dict:
    """Verify a sealed acquisition inventory and return a non-acceptance report."""
    _saved._case_suffix(case_id)
    root = attempt.resolve()
    acquisition_path = acquisition_path.resolve()
    if root not in acquisition_path.parents or not acquisition_path.is_file():
        raise ValueError('acquisition outside attempt')
    acquisition = json.loads(acquisition_path.read_text(encoding='utf-8'))
    if acquisition.get('case_id') != case_id or acquisition.get('cell_id') != 'C143687':
        raise ValueError('acquisition case or cell mismatch')
    if acquisition.get('frame_count') != 900 or acquisition.get('fps') != 20:
        raise ValueError('acquisition frame contract mismatch')
    history = acquisition.get('history', {})
    original = _confined(root, history.get('path'))
    expected = history.get('sha256')
    if not expected or _sha(original) != expected:
        raise ValueError('original history hash mismatch')
    native = _saved.audit_history(original, expected, case_id)
    media = acquisition.get('camera_media')
    if not isinstance(media, dict) or set(media) != set(CAMERAS):
        raise ValueError('four camera inventory missing')
    verified = {}
    for camera in CAMERAS:
        entry = media[camera]
        path = _confined(root, entry.get('path'))
        if not entry.get('sha256') or _sha(path) != entry['sha256']:
            raise ValueError(f'{camera} camera hash mismatch')
        if path.stat().st_size == 0:
            raise ValueError(f'{camera} camera empty')
        verified[camera] = {'path': entry['path'], 'sha256': entry['sha256']}
    return {
        'case_id': case_id,
        'acquisition_sha256': _sha(acquisition_path),
        'native_source': True,
        'all_participants': bool(native['entered_corridor']),
        'time_join': native['frame_count'] == 900,
        'camera_media': verified,
        'full_video_decode': False,
        'actual_pixels': False,
        'physical_completion': False,
        'legal_judgment': None,
    }


def audit_decoded(attempt: Path, acquisition_path: Path, case_id: str,
                  *, expected_dimensions=None) -> dict:
    """Join the sealed source audit with complete original 20 Hz video decode."""
    report = audit_saved(attempt, acquisition_path, case_id)
    root = Path(attempt).resolve()
    streams = {}
    for camera, ref in report['camera_media'].items():
        if (root / ref['path']).is_symlink():
            raise ValueError('camera symlink rejected')
        path = _confined(root, ref['path'])
        probe = subprocess.run(
            ['ffprobe', '-v', 'error', '-select_streams', 'v:0',
             '-show_entries', 'stream=width,height,r_frame_rate:frame=best_effort_timestamp_time',
             '-show_frames', '-of', 'json', str(path)],
            capture_output=True, text=True, check=False)
        if probe.returncode:
            raise ValueError('camera probe failed')
        data = json.loads(probe.stdout)
        stream = data.get('streams', [{}])[0]
        if stream.get('r_frame_rate') != '20/1':
            raise ValueError('camera rate differs from 20 Hz')
        if expected_dimensions is not None and (
            stream.get('width'), stream.get('height')) != tuple(expected_dimensions[camera]):
            raise ValueError('camera dimensions differ')
        try:
            times = [float(row['best_effort_timestamp_time']) for row in data['frames']]
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('camera frame timestamp missing') from exc
        if len(times) != 900 or any(abs((time - times[0]) - i / 20) > .001
                                     for i, time in enumerate(times)):
            raise ValueError('camera frame/time continuity failed')
        decoded = subprocess.run(
            ['ffmpeg', '-v', 'error', '-i', str(path), '-map', '0:v:0',
             '-f', 'null', '-'], capture_output=True, text=True, check=False)
        if decoded.returncode:
            raise ValueError('camera full decode failed')
        streams[camera] = {'sha256': ref['sha256'], 'decoded_frames': len(times),
                           'first_pts_s': times[0], 'last_pts_s': times[-1]}
    return {**report, 'full_video_decode': True, 'decoded_view_frames': 3600,
            'camera_streams': streams}

"""Four synchronized original RGB camera streams for a trail attempt."""
from __future__ import annotations

import math
from pathlib import Path
import queue
import subprocess


CAMERA_SPECS = {'overview': (1920, 1080), 'approach': (1280, 720),
                'reference_corner': (1280, 720), 'driver_reference': (1280, 720)}


def placements(site):
    box = site['corridor_box_xy']
    cx, cy = (box[0] + box[2]) / 2, (box[1] + box[3]) / 2
    start, end = site['route_xy'][0], site['route_xy'][-1]
    sign = site['sign']['position_xy']
    target = (cx, cy, 1.0)
    positions = {
        'overview': (cx, cy + 18, 25),
        'approach': (start[0] - 6, start[1] - 5, 5),
        'reference_corner': (sign[0] - 3, sign[1] + 5, 5),
        'driver_reference': (end[0] + 5, end[1] - 5, 5),
    }
    result = {}
    for name, point in positions.items():
        dx, dy, dz = (target[i] - point[i] for i in range(3))
        result[name] = {'location_xyz_m': point,
                        'pitch_deg': math.degrees(math.atan2(dz, math.hypot(dx, dy))),
                        'yaw_deg': math.degrees(math.atan2(dy, dx)),
                        'target_xyz_m': target}
    return result


def spawn_cameras(world, site, carla):
    positions = placements(site)
    sensors = {}
    try:
        for name, (width, height) in CAMERA_SPECS.items():
            blueprint = world.get_blueprint_library().find('sensor.camera.rgb')
            if blueprint is None:
                raise ValueError('Native RGB camera blueprint missing')
            for key, value in (('image_size_x', width), ('image_size_y', height), ('fov', 75)):
                blueprint.set_attribute(key, str(value))
            position = positions[name]
            x, y, z = position['location_xyz_m']
            sensor = world.spawn_actor(blueprint, carla.Transform(
                carla.Location(x=x, y=y, z=z),
                carla.Rotation(pitch=position['pitch_deg'], yaw=position['yaw_deg'])))
            if sensor is None:
                raise ValueError(name + ' Native camera spawn failed')
            sensors[name] = sensor
        return sensors
    except BaseException:
        for sensor in reversed(list(sensors.values())):
            sensor.destroy()
        raise


class FourViewJoin:
    def __init__(self, specs=None):
        self.specs = specs or CAMERA_SPECS
        self.previous = None

    def append(self, sample, images):
        frame, time_s = sample['frame'], sample['time_s']
        if self.previous is not None and (
                frame != self.previous[0] + 1 or abs(time_s - self.previous[1] - .05) > .005):
            raise ValueError('four-camera original frame/time discontinuity')
        if set(images) != set(self.specs):
            raise ValueError('four named original camera views required')
        receipt = {'case_id': sample['case_id'], 'frame': frame,
                   'time_s': time_s, 'vehicle_id': sample['vehicle_id'], 'cameras': {}}
        for name, (width, height) in self.specs.items():
            image = images[name]
            if (int(image.frame) != frame or int(image.width) != width or
                    int(image.height) != height or len(image.raw_data) != width * height * 4):
                raise ValueError(name + ' original camera frame or BGRA size differs')
            receipt['cameras'][name] = {'frame': frame, 'width': width,
                                        'height': height, 'pixel_format': 'bgra',
                                        'bytes': len(image.raw_data)}
        self.previous = (frame, time_s)
        return receipt


class FourVideoRecorder:
    def __init__(self, world, site, carla, output, encoder_factory=None):
        self.output = Path(output)
        if not self.output.is_dir() or any((self.output / (name + '.mkv')).exists() for name in CAMERA_SPECS):
            raise ValueError('fresh existing Native attempt required for videos')
        self.sensors, self.encoders, self.queues = {}, {}, {}
        self.errors = []
        self.closed = False
        self.join = FourViewJoin()
        encoder_factory = encoder_factory or subprocess.Popen
        try:
            self.sensors = spawn_cameras(world, site, carla)
            for name, (width, height) in CAMERA_SPECS.items():
                inbox = queue.Queue(maxsize=4)
                self.queues[name] = inbox

                def receive(image, target=inbox, label=name):
                    try:
                        target.put_nowait(image)
                    except queue.Full:
                        self.errors.append('camera queue overflow: ' + label)

                self.sensors[name].listen(receive)
                command = ['ffmpeg', '-nostdin', '-hide_banner', '-loglevel', 'error',
                           '-n', '-f', 'rawvideo', '-pixel_format', 'bgra',
                           '-video_size', f'{width}x{height}', '-framerate', '20',
                           '-i', 'pipe:0', '-an', '-c:v', 'ffv1', '-pix_fmt', 'bgra',
                           str(self.output / (name + '.mkv'))]
                self.encoders[name] = encoder_factory(
                    command, stdin=subprocess.PIPE, stderr=subprocess.DEVNULL)
        except BaseException:
            self.close()
            raise

    def append(self, sample, snapshot=None):
        if self.closed or self.errors:
            raise RuntimeError('Native video recorder closed or camera queue failed: ' + '; '.join(self.errors))
        images = {name: self.queues[name].get(timeout=15) for name in CAMERA_SPECS}
        receipt = self.join.append(sample, images)
        for name, image in images.items():
            written = self.encoders[name].stdin.write(image.raw_data)
            if written != len(image.raw_data):
                raise RuntimeError(name + ' encoder wrote incomplete original frame')
        return receipt

    def close(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        for sensor in reversed(list(self.sensors.values())):
            try: sensor.stop()
            except BaseException as exc: errors.append('sensor stop: ' + repr(exc))
        for name, encoder in self.encoders.items():
            try:
                if encoder.stdin and not encoder.stdin.closed:
                    encoder.stdin.close()
                if encoder.wait(timeout=180) != 0:
                    errors.append(name + ' encoder failed')
            except BaseException as exc:
                errors.append('encoder close: ' + repr(exc))
        for sensor in reversed(list(self.sensors.values())):
            try: sensor.destroy()
            except BaseException as exc: errors.append('sensor destroy: ' + repr(exc))
        if errors:
            raise RuntimeError('; '.join(errors))

